    ""
  );

  return (
    <form action={formAction}>
      <input name="name" />
      <button disabled={isPending} type="submit">
        {isPending ? "Saving…" : "Save"}
      </button>
      <p aria-live="polite">{state}</p>
    </form>
  );
}

